import { useState, useEffect, useRef } from "react";

const ARTIST_PHOTO = "data:image/jpeg;base64,";

// Paleta inspirada en la referencia: marfil, dorado, azul marino profundo.
const IVORY = "#F5F1E8";
const CARD = "#FBF9F4";
const GOLD = "#C6A15B";
const GOLD_DK = "#B08E44";
const NAVY = "#16233A";
const SLATE = "#5C6472";
const LINE = "#E7E0D1";

export default function MuseoCardosa() {
  const [works, setWorks] = useState([]);
  const [rooms, setRooms] = useState({});
  const [loading, setLoading] = useState(true);
  const [analyzing, setAnalyzing] = useState(false);
  const [tab, setTab] = useState("inicio"); // inicio | colecciones | salas
  const [activeRoom, setActiveRoom] = useState(null);
  const [activeWork, setActiveWork] = useState(null);
  const [error, setError] = useState("");
  const [query, setQuery] = useState("");
  const fileRef = useRef(null);

  useEffect(() => {
    (async () => {
      try {
        const res = await fetch("/.netlify/functions/works");
        if (res.ok) {
          const data = await res.json();
          const w = data.works || [];
          setWorks(w);
          setRooms(groupRooms(w));
        } else {
          setError("No se pudieron cargar las obras guardadas. Reintenta recargando la página.");
        }
      } catch (e) {
        setError("Sin conexión con el museo. Comprueba tu red y recarga la página.");
      }
      setLoading(false);
    })();
  }, []);

  function groupRooms(list) {
    const r = {};
    for (const w of list) {
      if (!r[w.room]) r[w.room] = [];
      r[w.room].push(w);
    }
    return r;
  }

  // Guarda una sola obra en la nube compartida.
  async function saveWork(work) {
    const res = await fetch("/.netlify/functions/works", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(work),
    });
    if (!res.ok) {
      let msg = "código " + res.status;
      try { const j = await res.json(); if (j.error) msg = j.error; } catch {}
      throw new Error("No se pudo guardar en la nube (" + msg + ")");
    }
  }

  // Borra una obra de la nube por id.
  async function removeStored(id) {
    const res = await fetch("/.netlify/functions/works?id=" + encodeURIComponent(id), { method: "DELETE" });
    if (!res.ok) throw new Error("delete falló");
  }

  // Vacía todo el museo en la nube.
  async function clearAllStored() {
    try {
      await fetch("/.netlify/functions/works?all=1", { method: "DELETE" });
    } catch (e) {
      console.error("vaciar error", e);
    }
  }

  function readAsDataUrl(file) {
    return new Promise((res, rej) => {
      const r = new FileReader();
      r.onload = () => res(r.result);
      r.onerror = () => rej(new Error("No se pudo leer el archivo"));
      r.readAsDataURL(file);
    });
  }

  function blobToDataUrl(blob) {
    return new Promise((res, rej) => {
      const r = new FileReader();
      r.onload = () => res(r.result);
      r.onerror = () => rej(new Error("No se pudo leer el resultado"));
      r.readAsDataURL(blob);
    });
  }

  // Reencodea a JPEG desde un elemento decodificado (bitmap o img).
  function encodeToJpeg(source, srcW, srcH, maxDim) {
    let width = srcW;
    let height = srcH;
    if (width > maxDim || height > maxDim) {
      const s = maxDim / Math.max(width, height);
      width = Math.round(width * s);
      height = Math.round(height * s);
    }
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext("2d");
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, width, height);
    ctx.drawImage(source, 0, 0, width, height);
    return canvas;
  }

  async function canvasToB64(canvas, quality) {
    const blob = await new Promise((res) => canvas.toBlob(res, "image/jpeg", quality));
    const dataUrl = blob ? await blobToDataUrl(blob) : canvas.toDataURL("image/jpeg", quality);
    return { b64: dataUrl.split(",")[1], dataUrl };
  }

  // Devuelve dos versiones: una para mostrar/guardar y otra más ligera para la API.
  async function makeVersions(source, w, h) {
    const displayCanvas = encodeToJpeg(source, w, h, 850);
    const display = await canvasToB64(displayCanvas, 0.8);
    const apiCanvas = encodeToJpeg(source, w, h, 640);
    const api = await canvasToB64(apiCanvas, 0.72);
    return { dataUrl: display.dataUrl, apiB64: api.b64 };
  }

  async function normalizeImage(file) {
    const apiTypes = ["image/jpeg", "image/png", "image/gif", "image/webp"];

    // Intento 1: createImageBitmap (rápido y amplio).
    try {
      const bitmap = await createImageBitmap(file);
      const v = await makeVersions(bitmap, bitmap.width, bitmap.height);
      bitmap.close?.();
      return { apiB64: v.apiB64, media: "image/jpeg", dataUrl: v.dataUrl };
    } catch {}

    // Intento 2: decodificar con <img> (Safari iOS a veces lee HEIC así).
    try {
      const objectUrl = URL.createObjectURL(file);
      const img = await new Promise((res, rej) => {
        const i = new Image();
        i.onload = () => res(i);
        i.onerror = () => rej(new Error("img decode"));
        i.src = objectUrl;
      });
      const v = await makeVersions(img, img.naturalWidth || img.width, img.naturalHeight || img.height);
      URL.revokeObjectURL(objectUrl);
      return { apiB64: v.apiB64, media: "image/jpeg", dataUrl: v.dataUrl };
    } catch {}

    // Intento 3: enviar el archivo tal cual si la API admite su tipo.
    const media = (file.type || "").toLowerCase();
    if (apiTypes.includes(media)) {
      const dataUrl = await readAsDataUrl(file);
      return { apiB64: dataUrl.split(",")[1], media, dataUrl };
    }

    throw new Error("Esta foto está en un formato que no se puede procesar (seguramente HEIC de iPhone). Haz una CAPTURA DE PANTALLA del dibujo y sube esa, o cambia en Ajustes › Cámara › Formatos a 'Más compatible'.");
  }

  function extractJson(text) {
    const clean = text.replace(/```json|```/g, "").trim();
    try {
      return JSON.parse(clean);
    } catch {}
    const start = clean.indexOf("{");
    const end = clean.lastIndexOf("}");
    if (start !== -1 && end !== -1 && end > start) {
      return JSON.parse(clean.slice(start, end + 1));
    }
    throw new Error("Respuesta sin JSON legible");
  }

  async function handleUpload(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    setError("");
    setAnalyzing(true);
    let phase = "leer imagen";
    try {
      const { apiB64, dataUrl, media } = await normalizeImage(file);
      phase = "contactar con el comisario";
      const existingRooms = Object.keys(rooms);

      const prompt = `Eres el comisario del Museo Cardosa, dedicado a la pintora ficticia Isabel Cardosa. Tienes un humor cálido y socarrón: aprecias el arte de verdad, pero eres honesto y te ríes con cariño de lo que ves. Si algo está torcido, raro, mal proporcionado o directamente feo, lo dices, pero SIEMPRE con gracia y ternura, nunca con crueldad ni para humillar. Ironía amable, guasa de amigo que te quiere. Se te presenta una obra inventada suya. Tu trabajo:

1. Un título evocador con un puntito de guasa (bonito y con gracia a la vez).
2. Una descripción MUY BREVE: máximo 2 frases. Con ironía cariñosa: señala con humor lo que está regular o tiene su encanto torpe, pero de forma tierna, como quien se ríe con la artista y no de ella. Debe sacar una sonrisa y, si acaso, dejar bien a Isabel al final. Ejemplos de tono:
- "Las proporciones se toman ciertas libertades creativas, pero el conjunto tiene un encanto que no se puede enseñar. Bien hecho, Isabel."
- "Puede que el dragón tenga cara de haber dormido mal, y precisamente por eso te roba el corazón."
- "Aquí Isabel demuestra que la perfección está sobrevalorada: esto es puro carácter."
3. Una SALA temática con nombre bonito y con un guiño (p.ej. "Sala de las Máscaras", "Sala de los Encantos Imperfectos", "Sala de las Buenas Intenciones").
${existingRooms.length ? `Salas existentes: ${existingRooms.join(", ")}. Reutiliza una si encaja; si no, crea otra.` : "Aún no hay salas; crea la primera."}
4. Un criterio de sala de UNA frase corta, con la misma ternura socarrona.

Responde SOLO con JSON válido, sin markdown:
{"title":"...","description":"...","room":"...","roomCriterion":"..."}`;

      const response = await fetch("/.netlify/functions/catalog", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          messages: [
            {
              role: "user",
              content: [
                { type: "image", source: { type: "base64", media_type: media, data: apiB64 } },
                { type: "text", text: prompt },
              ],
            },
          ],
        }),
      });
      phase = "leer la respuesta";
      const raw = await response.text();
      if (!response.ok) {
        // Intenta extraer el mensaje de error de la API.
        let msg = `código ${response.status}`;
        try { const j = JSON.parse(raw); msg = j.error?.message || msg; } catch {}
        throw new Error(`El comisario devolvió un error (${msg}). Prueba con una imagen más pequeña o una captura de pantalla.`);
      }
      let data;
      try {
        data = JSON.parse(raw);
      } catch {
        throw new Error("La respuesta llegó incompleta (imagen quizá demasiado grande). Prueba con una captura de pantalla del dibujo.");
      }
      if (!data.content) throw new Error("Respuesta vacía del comisario.");
      const text = data.content.filter((i) => i.type === "text").map((i) => i.text).join("\n");
      phase = "interpretar la ficha";
      const parsed = extractJson(text);
      if (!parsed.title || !parsed.room) throw new Error("Ficha incompleta.");

      const now = Date.now();
      const work = {
        id: now.toString() + "-" + Math.random().toString(36).slice(2, 8),
        createdAt: now,
        image: dataUrl,
        title: parsed.title,
        description: parsed.description,
        room: parsed.room,
        roomCriterion: parsed.roomCriterion,
        date: new Date().getFullYear(),
      };
      phase = "guardar la obra";
      await saveWork(work); // si falla, salta al catch y no se añade a la vista
      const next = [work, ...works];
      setWorks(next);
      setRooms(groupRooms(next));
      setActiveWork(work);
    } catch (err) {
      setError(`No se pudo catalogar la obra (fase: ${phase}): ${err.message || "error desconocido"}.`);
    }
    setAnalyzing(false);
    if (fileRef.current) fileRef.current.value = "";
  }

  async function resetMuseum() {
    if (!confirm("¿Vaciar el museo por completo?")) return;
    await clearAllStored();
    setWorks([]);
    setRooms({});
    setActiveWork(null);
    setActiveRoom(null);
    setTab("inicio");
  }

  async function deleteWork(id) {
    if (!confirm("¿Retirar esta obra de la colección?")) return;
    const prev = works;
    const next = works.filter((w) => w.id !== id);
    setWorks(next);
    const nextRooms = groupRooms(next);
    setRooms(nextRooms);
    setActiveWork(null);
    if (activeRoom && !nextRooms[activeRoom]) setActiveRoom(null);
    try {
      await removeStored(id);
    } catch (e) {
      // Si el borrado en la nube falla, restauramos la vista para no engañar.
      setWorks(prev);
      setRooms(groupRooms(prev));
      setError("No se pudo retirar la obra. Inténtalo de nuevo.");
    }
  }

  const roomNames = Object.keys(rooms);
  const pick = () => fileRef.current?.click();

  return (
    <div style={{ minHeight: "100vh", background: IVORY, color: NAVY, fontFamily: "'Helvetica Neue', Arial, sans-serif", paddingBottom: 96 }}>
      <style>{`
        * { box-sizing: border-box; }
        .serif { font-family: Georgia, 'Times New Roman', serif; }
        .label { text-transform: uppercase; letter-spacing: 0.16em; }
        .card { background: ${CARD}; border: 1px solid ${LINE}; border-radius: 22px; }
        .shadow { box-shadow: 0 8px 30px rgba(22,35,58,.07); }
        .pill { border-radius: 999px; cursor: pointer; border: none; font-weight: 600; letter-spacing: .02em; transition: transform .15s, opacity .2s; }
        .pill:active { transform: scale(.97); }
        .fade { animation: f .45s ease; }
        @keyframes f { from { opacity:0; transform: translateY(10px);} to {opacity:1; transform:none;} }
        .thumb { background-size: cover; background-position: center; background-color:#fff; }
        .tap { cursor: pointer; }
        .navbtn { flex:1; display:flex; flex-direction:column; align-items:center; gap:4px; background:none; border:none; cursor:pointer; padding:8px 0; font-size:11px; letter-spacing:.05em; }
        .spin { animation: sp 1s linear infinite; }
        @keyframes sp { to { transform: rotate(360deg);} }
        .work-split { display:grid; grid-template-columns: minmax(0,1.2fr) minmax(0,1fr); gap:40px; align-items:start; }
        @media (max-width: 760px){ .work-split{ grid-template-columns:1fr; gap:24px; } }
      `}</style>

      {/* Logo header */}
      <header style={{ textAlign: "center", padding: "18px 20px 16px", borderBottom: `1px solid ${LINE}`, background: IVORY, position: "sticky", top: 0, zIndex: 20 }}>
        <div className="tap" onClick={() => { setActiveWork(null); setActiveRoom(null); setTab("inicio"); }} style={{ display: "inline-flex", alignItems: "center", gap: 12 }}>
          <Emblem />
          <div style={{ textAlign: "left", lineHeight: 1 }}>
            <div className="serif" style={{ fontSize: 20, letterSpacing: ".14em", color: NAVY }}>MUSEO</div>
            <div className="serif" style={{ fontSize: 20, letterSpacing: ".22em", color: GOLD_DK }}>CARDOSA</div>
          </div>
        </div>
      </header>

      <input ref={fileRef} type="file" accept="image/*" onChange={handleUpload} style={{ display: "none" }} />

      {error && (
        <div style={{ margin: "14px 18px 0", background: "#8a2e2e", color: "#fff", padding: "12px 16px", borderRadius: 14, fontSize: 13.5 }}>{error}</div>
      )}
      {analyzing && (
        <div style={{ margin: "14px 18px 0", background: "#fff7e6", border: `1px solid ${GOLD}`, color: GOLD_DK, padding: "12px 16px", borderRadius: 14, fontSize: 13.5, display: "flex", alignItems: "center", gap: 10 }}>
          <span className="spin" style={{ width: 14, height: 14, border: `2px solid ${GOLD}`, borderTopColor: "transparent", borderRadius: "50%", display: "inline-block" }} />
          El comisario está estudiando la pieza…
        </div>
      )}

      <main style={{ maxWidth: 760, margin: "0 auto", padding: "20px 18px 40px" }}>
        {loading ? (
          <p style={{ color: SLATE }}>Abriendo el museo…</p>
        ) : activeWork ? (
          <WorkView work={activeWork} onBack={() => setActiveWork(null)} onRoom={(r) => { setActiveRoom(r); setActiveWork(null); setTab("salas"); }} onDelete={deleteWork} />
        ) : activeRoom ? (
          <RoomView name={activeRoom} works={rooms[activeRoom] || []} onBack={() => setActiveRoom(null)} onWork={setActiveWork} />
        ) : tab === "inicio" ? (
          <Home works={works} roomNames={roomNames} onUpload={pick} analyzing={analyzing} onReset={resetMuseum} />
        ) : tab === "colecciones" ? (
          <Collections works={works} onWork={setActiveWork} onUpload={pick} query={query} setQuery={setQuery} />
        ) : (
          <Rooms rooms={rooms} roomNames={roomNames} onRoom={setActiveRoom} onUpload={pick} />
        )}
      </main>

      {/* Bottom nav */}
      <nav style={{ position: "fixed", bottom: 0, left: 0, right: 0, background: "#fff", borderTop: `1px solid ${LINE}`, display: "flex", padding: "6px 10px calc(6px + env(safe-area-inset-bottom))", zIndex: 20, boxShadow: "0 -4px 20px rgba(22,35,58,.05)" }}>
        <button className="navbtn" onClick={() => { setActiveWork(null); setActiveRoom(null); setTab("inicio"); }} style={{ color: tab === "inicio" && !activeRoom && !activeWork ? GOLD_DK : SLATE }}>
          <IconHome active={tab === "inicio"} /> Inicio
        </button>
        <button className="navbtn" onClick={() => { setActiveWork(null); setActiveRoom(null); setTab("colecciones"); }} style={{ color: tab === "colecciones" ? GOLD_DK : SLATE }}>
          <IconGrid /> Obras
        </button>
        <button className="navbtn" onClick={() => { setActiveWork(null); setActiveRoom(null); setTab("salas"); }} style={{ color: tab === "salas" ? GOLD_DK : SLATE }}>
          <IconMuseum /> Salas
        </button>
      </nav>

      {/* Floating upload */}
      {!activeWork && (
        <button className="pill shadow" onClick={pick} disabled={analyzing} style={{ position: "fixed", left: 18, right: 18, bottom: "calc(72px + env(safe-area-inset-bottom))", maxWidth: 724, margin: "0 auto", background: GOLD, color: "#fff", padding: "16px", fontSize: 16, display: "flex", alignItems: "center", justifyContent: "center", gap: 8, zIndex: 19 }}>
          + Subir obra
        </button>
      )}
    </div>
  );
}

function Home({ works, roomNames, onUpload, analyzing, onReset }) {
  return (
    <div className="fade">
      {/* Hero */}
      <section className="card" style={{ padding: "28px 24px", marginBottom: 18, position: "relative", overflow: "hidden" }}>
        <h1 className="serif" style={{ fontSize: 34, lineHeight: 1.12, margin: "0 0 10px", maxWidth: "78%" }}>
          Bienvenido al<br />Museo <span style={{ color: GOLD_DK }}>Cardosa</span>
        </h1>
        <p style={{ color: SLATE, fontSize: 15, margin: 0, maxWidth: "78%" }}>El arte de Isabel Cardosa, catalogado por una IA con demasiadas opiniones.</p>
        <div style={{ position: "absolute", right: -10, bottom: -6, opacity: .5 }}><Temple /></div>
      </section>

      {/* Artista */}
      <section className="card" style={{ padding: 18, marginBottom: 18, display: "flex", gap: 16, alignItems: "center" }}>
        <img src={ARTIST_PHOTO} alt="Isabel Cardosa" style={{ width: 74, height: 74, borderRadius: "50%", objectFit: "cover", flexShrink: 0, border: `2px solid ${GOLD}` }} />
        <div style={{ minWidth: 0 }}>
          <div className="label" style={{ fontSize: 10, color: GOLD_DK, marginBottom: 4 }}>La artista</div>
          <div className="serif" style={{ fontSize: 20, lineHeight: 1.1 }}>Isabel Cardosa</div>
          <p style={{ color: SLATE, fontSize: 13, margin: "5px 0 0", lineHeight: 1.45 }}>Pintora de lo inefable. Cada trazo esconde un universo (o eso dice el comisario).</p>
        </div>
      </section>

      {/* Upload card */}
      <section className="card" style={{ padding: 24, marginBottom: 18 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 16 }}>
          <div style={{ flex: 1 }}>
            <div style={{ width: 52, height: 52, borderRadius: "50%", border: `1.5px solid ${GOLD}`, display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 16 }}>
              <span style={{ color: GOLD_DK, fontSize: 22 }}>↑</span>
            </div>
            <h2 className="serif" style={{ fontSize: 23, margin: "0 0 8px" }}>Sube una imagen de tu obra</h2>
            <p style={{ color: SLATE, fontSize: 14.5, lineHeight: 1.5, margin: 0 }}>
              El comisario la analiza y genera nombre, descripción y sala automáticamente. Pulsa <b style={{ color: GOLD_DK }}>Subir obra</b> abajo para empezar.
            </p>
          </div>
          <div className="card" style={{ width: 92, height: 92, borderColor: GOLD, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 40, flexShrink: 0 }}>🎨</div>
        </div>
      </section>

      {/* Stats */}
      <section style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", textAlign: "center", borderTop: `1px solid ${LINE}`, borderBottom: `1px solid ${LINE}` }}>
        <Stat value={works.length} label="Obras" />
        <Stat value={roomNames.length} label="Salas" divider />
        <Stat value="∞" label="Emoción" />
      </section>

      {works.length > 0 && (
        <div style={{ textAlign: "center", marginTop: 24 }}>
          <button className="pill" onClick={onReset} style={{ background: "transparent", border: `1px solid ${LINE}`, color: SLATE, padding: "10px 20px", fontSize: 13 }}>Vaciar museo</button>
        </div>
      )}
    </div>
  );
}

function Stat({ value, label, divider }) {
  return (
    <div style={{ padding: "22px 8px", borderLeft: divider ? `1px solid ${LINE}` : "none", borderRight: divider ? `1px solid ${LINE}` : "none" }}>
      <div className="serif" style={{ fontSize: 30, color: NAVY }}>{value}</div>
      <div className="label" style={{ fontSize: 11, color: SLATE, marginTop: 4 }}>{label}</div>
    </div>
  );
}

function Collections({ works, onWork, onUpload, query, setQuery }) {
  if (works.length === 0) return <Empty onUpload={onUpload} title="Aún no hay obras" text="Dona la primera y aparecerá aquí, catalogada con toda la pompa del mundo." />;
  const q = query.trim().toLowerCase();
  const filtered = q
    ? works.filter((w) =>
        [w.title, w.room, w.description].filter(Boolean).some((t) => t.toLowerCase().includes(q))
      )
    : works;
  return (
    <div className="fade">
      <SectionTitle eyebrow="Obras" title="Todas las obras" note={`${works.length} ${works.length === 1 ? "pieza" : "piezas"}`} />
      <div style={{ position: "relative", marginBottom: 18 }}>
        <span style={{ position: "absolute", left: 16, top: "50%", transform: "translateY(-50%)", color: SLATE, fontSize: 15 }}>⌕</span>
        <input
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Buscar por título, sala o palabra…"
          style={{ width: "100%", padding: "13px 16px 13px 40px", borderRadius: 999, border: `1px solid ${LINE}`, background: CARD, fontSize: 14.5, color: NAVY, outline: "none", fontFamily: "inherit" }}
        />
        {query && (
          <button onClick={() => setQuery("")} style={{ position: "absolute", right: 12, top: "50%", transform: "translateY(-50%)", border: "none", background: "none", color: SLATE, fontSize: 18, cursor: "pointer", lineHeight: 1 }}>×</button>
        )}
      </div>
      {filtered.length === 0 ? (
        <p style={{ color: SLATE, fontSize: 14.5, textAlign: "center", padding: "30px 0", fontStyle: "italic" }}>
          Ni el comisario encuentra nada para «{query}».
        </p>
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
          {filtered.map((w) => (
            <div key={w.id} className="card tap" onClick={() => onWork(w)} style={{ overflow: "hidden" }}>
              <div className="thumb" style={{ aspectRatio: "1/1", backgroundImage: `url(${w.image})` }} />
              <div style={{ padding: "12px 14px 16px" }}>
                <div className="serif" style={{ fontSize: 16, lineHeight: 1.2, marginBottom: 6 }}>{w.title}</div>
                <div className="label" style={{ fontSize: 9.5, color: GOLD_DK }}>{w.room}</div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function Rooms({ rooms, roomNames, onRoom, onUpload }) {
  if (roomNames.length === 0) return <Empty onUpload={onUpload} title="Aún no hay salas" text="Cada obra que dones abrirá o llenará una sala temática. El museo se construye solo." />;
  return (
    <div className="fade">
      <SectionTitle eyebrow="Planta de salas" title="Recorrido de la colección" note={`${roomNames.length} ${roomNames.length === 1 ? "sala" : "salas"}`} />
      <div style={{ display: "grid", gap: 16 }}>
        {roomNames.map((name) => {
          const rw = rooms[name];
          return (
            <div key={name} className="card tap" onClick={() => onRoom(name)} style={{ padding: 18, display: "flex", gap: 16, alignItems: "center" }}>
              <div style={{ display: "grid", gridTemplateColumns: rw.length >= 2 ? "1fr 1fr" : "1fr", gap: 4, width: 92, flexShrink: 0 }}>
                {rw.slice(0, 4).map((w) => (
                  <div key={w.id} className="thumb" style={{ aspectRatio: "1/1", backgroundImage: `url(${w.image})`, borderRadius: 8 }} />
                ))}
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div className="serif" style={{ fontSize: 19, lineHeight: 1.15, marginBottom: 5 }}>{name}</div>
                <div style={{ fontSize: 13, color: SLATE, fontStyle: "italic", lineHeight: 1.45, marginBottom: 8 }}>{rw[0]?.roomCriterion}</div>
                <div className="label" style={{ fontSize: 10, color: GOLD_DK }}>{rw.length} {rw.length === 1 ? "obra" : "obras"} →</div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function RoomView({ name, works, onBack, onWork }) {
  return (
    <div className="fade">
      <BackBtn onClick={onBack} label="Salas" />
      <SectionTitle eyebrow="Sala" title={name} note={works[0]?.roomCriterion} italicNote />
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
        {works.map((w) => (
          <div key={w.id} className="card tap" onClick={() => onWork(w)} style={{ overflow: "hidden" }}>
            <div className="thumb" style={{ aspectRatio: "1/1", backgroundImage: `url(${w.image})` }} />
            <div style={{ padding: "12px 14px 16px" }}>
              <div className="serif" style={{ fontSize: 16, lineHeight: 1.2 }}>{w.title}</div>
              <div className="label" style={{ fontSize: 9.5, color: SLATE, marginTop: 5 }}>Isabel Cardosa · {w.date}</div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function WorkView({ work, onBack, onRoom, onDelete }) {
  if (!work) return null;
  return (
    <div className="fade work-split">
      <div>
        <BackBtn onClick={onBack} label="Volver" />
        <div className="card shadow" style={{ padding: 12, overflow: "hidden" }}>
          <img src={work.image} alt={work.title} style={{ width: "100%", display: "block", borderRadius: 12 }} />
        </div>
      </div>
      <div className="card" style={{ padding: 24 }}>
        <div className="label" style={{ fontSize: 10, color: GOLD_DK, marginBottom: 12 }}>Ficha técnica</div>
        <h2 className="serif" style={{ fontSize: 26, lineHeight: 1.15, margin: "0 0 6px", overflowWrap: "break-word" }}>{work.title}</h2>
        <div className="label" style={{ fontSize: 11, color: SLATE, marginBottom: 20 }}>Isabel Cardosa · {work.date}</div>
        <p className="serif" style={{ fontSize: 18, lineHeight: 1.6, color: NAVY, margin: 0, fontStyle: "italic" }}>{work.description}</p>
        <div style={{ marginTop: 24, paddingTop: 18, borderTop: `1px solid ${LINE}` }}>
          <div className="label" style={{ fontSize: 10, color: SLATE, marginBottom: 8 }}>Expuesta en</div>
          <div className="serif tap" style={{ fontSize: 18, color: GOLD_DK }} onClick={() => onRoom(work.room)}>{work.room} →</div>
        </div>
        <button
          className="pill"
          onClick={() => onDelete(work.id)}
          style={{ marginTop: 22, background: "transparent", border: "1px solid #d9c2c2", color: "#8a2e2e", padding: "11px 18px", fontSize: 13 }}
        >
          Retirar obra de la colección
        </button>
      </div>
    </div>
  );
}

function SectionTitle({ eyebrow, title, note, italicNote }) {
  return (
    <div style={{ marginBottom: 20 }}>
      <div className="label" style={{ fontSize: 11, color: GOLD_DK }}>{eyebrow}</div>
      <h2 className="serif" style={{ fontSize: 28, fontWeight: 400, margin: "6px 0 6px", lineHeight: 1.1 }}>{title}</h2>
      {note && <p style={{ color: SLATE, fontSize: 13.5, margin: 0, fontStyle: italicNote ? "italic" : "normal", maxWidth: 520 }}>{note}</p>}
    </div>
  );
}

function BackBtn({ onClick, label }) {
  return (
    <button className="pill" onClick={onClick} style={{ background: "transparent", border: `1px solid ${LINE}`, color: NAVY, padding: "9px 16px", fontSize: 12.5, marginBottom: 20 }}>← {label}</button>
  );
}

function Empty({ onUpload, title, text }) {
  return (
    <div className="fade card" style={{ padding: "40px 26px", textAlign: "center" }}>
      <div style={{ fontSize: 40, marginBottom: 12 }}>🖼️</div>
      <h2 className="serif" style={{ fontSize: 24, margin: "0 0 10px" }}>{title}</h2>
      <p style={{ color: SLATE, fontSize: 14.5, lineHeight: 1.5, maxWidth: 340, margin: "0 auto 22px" }}>{text}</p>
      <button className="pill" onClick={onUpload} style={{ background: GOLD, color: "#fff", padding: "13px 24px", fontSize: 15 }}>Donar una obra</button>
    </div>
  );
}

